<?php require '_guard.php';$stats=[(int)$pdo->query("SELECT COUNT(*) FROM tournaments")->fetchColumn(),(int)$pdo->query("SELECT COUNT(*) FROM registrations")->fetchColumn(),(int)$pdo->query("SELECT COUNT(*) FROM registrations WHERE status IN ('pending_payment','payment_review')")->fetchColumn(),(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='verified'")->fetchColumn()];$rows=$pdo->query("SELECT r.*,t.name AS tn,p.status AS ps FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id LEFT JOIN payments p ON p.registration_id=r.registration_id ORDER BY r.created_at DESC LIMIT 8")->fetchAll();$pageTitle='Admin control room';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">CONTROL ROOM / ADMIN</div><h1>RUN THE <span>ARENA.</span></h1><p>Welcome, <?=e($_SESSION['admin_username']??'Admin')?>. Here's the latest activity.</p></section><?php require 'nav.php';?><div class="admin-metrics"><div><small>TOURNAMENTS</small><b><?=$stats[0]?></b></div><div><small>ENTRIES</small><b><?=$stats[1]?></b></div><div><small>NEEDS REVIEW</small><b><?=$stats[2]?></b></div><div><small>MANUALLY VERIFIED</small><b>₹<?=number_format($stats[3])?></b></div></div><section class="box section"><div class="section-head"><div><div class="eyebrow">LATEST ACTIVITY</div><h2>RECENT <span>ENTRIES.</span></h2></div></div><div class="table-responsive"><table class="table arena-table"><thead><tr><th>TEAM / ID</th><th>TOURNAMENT</th><th>ENTRY</th><th>PAYMENT</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['team_name'])?></b><small><?=e($r['registration_code'])?></small></td><td><?=e($r['tn'])?></td><td><?=e(str_replace('_',' ',$r['status']))?></td><td><?=e(str_replace('_',' ',$r['ps']??'unpaid'))?></td><td><a class="text-link" href="registrations.php">Manage ↗</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
